        || x.abs() > 1.0e6
        || y.abs() > 1.0e6
        || width > 1.0e6
        || height > 1.0e6
    {
        return Err(err(MappingErrorKind::Number, element_offset));
    }
    let default = NestedViewport {
        child_transform: element_transform,
        viewport_transform: Affine {
            e: x,
            f: y,
            ..identity()
