        clip_points: [Point { x: 0.0, y: 0.0 }; 4],
        child_width: width,
        child_height: height,
        empty: false,
    };
    if width == 0.0 || height == 0.0 {
        return Ok(NestedViewport {
            empty: true,
            ..default
        });
    }
    let local = [
        Point { x, y },
        Point { x: x + width, y },
        Point {
            x: x + width,
            y: y + height,
