        start += 1
    }
    while end > start && matches!(bytes[end - 1], b' ' | b'\t' | b'\r' | b'\n') {
        end -= 1
    }
    bytes = &bytes[start..end];
    let percent = bytes.last() == Some(&b'%');
    let number_len = bytes.len() - usize::from(percent);
    let span = XmlSpan {
        offset: value.span.offset + start,
