fn matching_end(tokens: &[vexel_xml::XmlToken], start: usize) -> Option<usize> {
    let t = tokens.get(start)?;
    if t.kind == TokenKind::EmptyElement {
        return Some(start);
    }
    tokens
        .get(start + 1..)?
        .iter()
        .position(|v| v.kind == TokenKind::EndElement && v.depth == t.depth)
        .map(|n| start + 1 + n)
}

